<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { CarTaxiFront, ArrowRight } from 'lucide-vue-next'
import { register } from '../services/auth'
const router=useRouter(), name=ref(''), email=ref(''), phone=ref(''), password=ref(''), confirm=ref(''), error=ref('')
function submit(){error.value='';if(password.value!==confirm.value){error.value='Passwords do not match.';return}try{register({name:name.value,email:email.value,phone:phone.value,password:password.value});router.push('/passenger/bookings')}catch(e){error.value=e.message}}
</script>
<template><div class="auth-layout"><section class="auth-visual"><div class="auth-brand"><div class="brand-mark"><CarTaxiFront/></div><strong>TaxiGo</strong></div><div class="visual-copy"><div class="eyebrow light"><span></span> YOUR NEXT RIDE STARTS HERE</div><h1>Move through<br/>your day with <em>ease.</em></h1><p>Create an account to request rides and keep your booking history in one place.</p></div><div class="visual-footer">Educational demo · Local browser storage</div><div class="visual-decoration deco-one"></div><div class="visual-decoration deco-two"></div></section><section class="auth-main"><div class="auth-card"><div class="auth-mobile-brand"><div class="brand-mark"><CarTaxiFront/></div><strong>TaxiGo</strong></div><div class="eyebrow">GET STARTED</div><h2>Create your account</h2><p class="muted auth-intro">Register as a passenger to book rides.</p><form class="form-stack" @submit.prevent="submit"><label>Full name<input v-model.trim="name" required minlength="2" autocomplete="name" placeholder="Your full name"/></label><label>Email address<input v-model.trim="email" type="email" required autocomplete="email" placeholder="you@example.com"/></label><label>Contact number<input v-model.trim="phone" required autocomplete="tel" placeholder="09XX XXX XXXX"/></label><div class="form-grid"><label>Password<input v-model="password" type="password" minlength="8" required autocomplete="new-password" placeholder="At least 8 characters"/></label><label>Confirm password<input v-model="confirm" type="password" required autocomplete="new-password" placeholder="Repeat password"/></label></div><p v-if="error" class="form-error">{{error}}</p><button class="btn btn-primary btn-full" type="submit">Create account <ArrowRight :size="17"/></button></form><p class="auth-switch">Already have an account? <RouterLink to="/login">Sign in</RouterLink></p><p class="tiny-note">Do not use real or sensitive passwords in this demo.</p></div></section></div></template>